<?php
session_start(); require_once "../config/database.php";
if(!isset($_SESSION["user_id"])||$_SESSION["role"]!=="customer"){header("Location: ../auth/login.php");exit();}
$id=$_SESSION["user_id"];
function cnt($c,$id,$status=null){if($status===null){$s=$c->prepare("SELECT COUNT(*) n FROM shipments WHERE customer_id=?");$s->bind_param("i",$id);}else{$s=$c->prepare("SELECT COUNT(*) n FROM shipments WHERE customer_id=? AND status=?");$s->bind_param("is",$id,$status);}$s->execute();$n=$s->get_result()->fetch_assoc()["n"];$s->close();return $n;}
$total=cnt($conn,$id);$booked=cnt($conn,$id,"Booked");$transit=cnt($conn,$id,"In Transit");$delivered=cnt($conn,$id,"Delivered");
?>
